"use client";

import { useId, useState } from "react";

import { Switch } from "@/components/ui/switch";
import { MoonIcon, SunIcon } from "lucide-react";

export default function Component() {
	const id = useId();
	const [checked, setChecked] = useState(false);

	const toggleSwitch = () => setChecked((prev) => !prev);

	return (
		<div
			className="group inline-flex items-center gap-2"
			data-state={checked ? "checked" : "unchecked"}
		>
			<span
				id={`${id}-off`}
				className="group-data-[state=checked]:text-muted-foreground/70 flex-1 cursor-pointer text-right text-sm font-medium"
				aria-controls={id}
				onClick={() => setChecked(false)}
			>
				<MoonIcon size={16} aria-hidden="true" />
			</span>
			<Switch
				id={id}
				checked={checked}
				onCheckedChange={toggleSwitch}
				aria-labelledby={`${id}-off ${id}-on`}
				aria-label="Toggle between dark and light mode"
			/>
			<span
				id={`${id}-on`}
				className="group-data-[state=unchecked]:text-muted-foreground/70 flex-1 cursor-pointer text-left text-sm font-medium"
				aria-controls={id}
				onClick={() => setChecked(true)}
			>
				<SunIcon size={16} aria-hidden="true" />
			</span>
		</div>
	);
}

"use client";

import React from "react";

import { cn } from "@/lib/utils";
import * as SwitchPrimitives from "@radix-ui/react-switch";

const Switch = React.forwardRef<
	React.ElementRef<typeof SwitchPrimitives.Root>,
	React.ComponentPropsWithoutRef<typeof SwitchPrimitives.Root>
>(({ className, ...props }, ref) => (
	<SwitchPrimitives.Root
		className={cn(
			"peer inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 data-[state=checked]:bg-primary data-[state=unchecked]:bg-input",
			className
		)}
		{...props}
		ref={ref}
	>
		<SwitchPrimitives.Thumb
			className={cn(
				"pointer-events-none block h-5 w-5 rounded-full bg-background shadow-lg ring-0 transition-transform data-[state=checked]:translate-x-5 data-[state=unchecked]:translate-x-0"
			)}
		/>
	</SwitchPrimitives.Root>
));
Switch.displayName = SwitchPrimitives.Root.displayName;

export { Switch };
